          if(!inSite(area)||!zoneHasCorridorAccess(zone,objects)||objects.some(o=>['column','blocked','corridor','room','zone'].includes(o.type)&&overlap(area,rect(o)))||furniture.some(f=>overlap(area,furnitureRect(f))))continue;
