function draftScore(d,brief,mode){const m=d.meta,roomGap=brief?Math.max(0,brief.meetingRooms-m.meetings)+Math.max(0,brief.offices-m.offices)+Math.max(0,(brief.pantry?1:0)-m.pantries):0,seatGap=Math.max(0,m.requested-m.seats),phoneGap=Math.max(0,(brief?.phones??0)-m.phones),sharedGap=brief?Math.max(0,(+brief.diningSeats||0)-m.diningSeats)+Math.max(0,(+brief.loungeSeats||0)-m.loungeSeats)+4*Math.max(0,(brief.coffeeBar?1:0)-m.coffeeBars)+4*Math.max(0,(brief.reception?1:0)-m.receptions):0,preference=mode==='private'&&d.layoutPattern==='perimeter'?15:mode==='open'&&d.layoutPattern==='spine'?15:mode==='hybrid'&&d.layoutPattern==='neighborhood'?15:0;return roomGap*50+seatGap*10+phoneGap*50+sharedGap*20-preference}
function generateDrafts(){if(readOnly)return;const readiness=siteReadiness();if(!readiness.ready){$('#hint').textContent=readiness.recognitionPending?'Use the dimension-based fallback or complete assisted import before generating concepts.':'Mark at least one entrance and one emergency exit before generating concepts.';render();return}const people=Math.max(4,+$('#briefPeople').value||36),meeting=Math.max(0,+$('#briefMeeting').value||0),phone=Math.max(0,+$('#briefPhone').value||0),mode=$('#briefMode').value;const patterns=['spine','core','perimeter','neighborhood'];snapshot();comparisonCollapsed=false;P.site.confirmed=true;P.site.confirmedAt=new Date().toISOString();P.draftsStale=false;const candidates=patterns.map(pattern=>concept(pattern,people,meeting,phone,mode==='private'?'private':'hybrid'));candidates.sort((a,b)=>draftScore(a,P.broker,mode)-draftScore(b,P.broker,mode)||patterns.indexOf(a.layoutPattern)-patterns.indexOf(b.layoutPattern));P.drafts=candidates.slice(0,3);applyDraft(P.drafts[0].id,false);save()}
