  $('#comparisonGrid').innerHTML=drafts.map((d,index)=>{const rows=comparisonMeasures(d.objects,d.furniture,d.meta),gaps=rows.filter(r=>r.shortfall),takeaway=(gaps.length?`Still needed: ${gaps.map(r=>`${r.name} ${r.shortfall}`).join(' · ')}.`:'Shown quantities placed as concepts; professional review still needed.')+(unassessed?` ${unassessed} additional requirement(s) not assessed.`:'');return `<button class="comparison-card ${d.id===P.activeDraft?'active':''}" type="button" data-compare-draft="${esc(d.id)}" aria-pressed="${d.id===P.activeDraft}" ${readOnly||P.draftsStale?'disabled':''}><span class="comparison-card-head"><b>${'ABC'[index]} · ${esc(d.label)}</b><small>${d.id===P.activeDraft?'Viewing':'View plan'}</small></span><span class="comparison-purpose">${esc(d.purpose)}</span>${comparisonThumbnail(d)}${rows.map(r=>`<span class="comparison-row ${r.shortfall?'short':''}"><span>${esc(r.name)}</span><b>${r.actual}/${r.required}</b></span>`).join('')}<span class="comparison-takeaway">${esc(takeaway)}</span></button>`}).join('');
  const current=$('#comparisonCurrent');current.hidden=!edited&&!P.draftsStale;if(P.draftsStale)current.textContent='Site or needs changed. These generated snapshots are out of date; regenerate before comparing.';else if(edited){const rows=comparisonMeasures(P.objects,P.furniture,active.meta);current.textContent=`Current edited plan (not the snapshot): ${rows.map(r=>`${r.name} ${r.actual}/${r.required}`).join(' · ')}. Recheck basic conflicts and access before sharing.`}
