function renderDrafts(){const host=$('#drafts'),drafts=P.drafts||[];if(!drafts.length){host.innerHTML='<div class="empty">Complete the brief to generate plans.</div>';return}host.innerHTML=(P.draftsStale?'<div class="status warn">These concepts use an earlier site revision. Regenerate before sharing.</div>':'')+drafts.map(d=>{const gap=Math.max(0,d.meta.requested-d.meta.seats),active=d.id===P.activeDraft,rooms=P.broker?` · Meeting rooms ${d.meta.meetings}/${P.broker.meetingRooms} · Offices ${d.meta.offices}/${P.broker.offices} · Pantry ${d.meta.pantries}/${P.broker.pantry?1:0}`:` · Meeting seats ${d.meta.meetings}`,roomGap=P.broker?Math.max(0,P.broker.meetingRooms-d.meta.meetings)+Math.max(0,P.broker.offices-d.meta.offices)+Math.max(0,(P.broker.pantry?1:0)-d.meta.pantries):0;return `<button class="tool ${active?'active':''}" data-draft="${d.id}" ${readOnly||P.draftsStale?'disabled':''}><b>${d.label}${active?' · Selected':''}</b><small>${d.purpose}</small><small>Seats ${d.meta.seats}/${d.meta.requested}${rooms} · Booths ${d.meta.phones}/${P.broker?.phones??$('#briefPhone').value}${gap?` · ${gap} seats short`:''}${roomGap?` · ${roomGap} rooms short`:''}</small></button>`}).join('');host.querySelectorAll('[data-draft]').forEach(b=>b.onclick=()=>{applyDraft(b.dataset.draft);save()})}
