cv.addEventListener('pointerdown',e=>{const [x,y]=pointer(e);if(e.button===1||spaceDown){drag={pan:true,x:e.clientX,y:e.clientY,vx:V.x,vy:V.y};return}if(readOnly)return;if(tool==='select'){const h=hit(x,y);selected=h?.id||null;if(h){snapshot();drag={move:h,ox:x-h.x,oy:y-h.y,changed:false}}render();return}snapshot();if(['door','window','exit'].includes(tool)){const placedType=tool,wall=P.objects.find(o=>o.type==='wall'&&lineHit(o,{x:o.x2,y:o.y2},x,y));if(!wall){history.pop();$('#hint').textContent=`Move closer to an exterior wall, then click to place the ${placedType==='door'?'entrance':placedType}.`;return}markSiteChanged();P.objects.push({id:id(),type:placedType,x:clamp(x),y:clamp(y),wallId:wall.id});selected=P.objects.at(-1).id;if(placedType==='door'&&!P.objects.some(o=>o.type==='exit'))tool='exit';else if(placedType==='exit')tool='select';setTool();save();return}const roomKind={meetingRoom:'meeting',officeRoom:'office',pantryRoom:'pantry'}[tool];if(!roomKind)markSiteChanged();drag={create:roomKind?{id:id(),type:'room',kind:roomKind,name:roomNames[roomKind],plannedSeats:roomKind==='meeting'?Number(P.broker?.roomSeats)||6:0,x:clamp(x),y:clamp(y),x2:clamp(x),y2:clamp(y),door:{side:'south',width:900},conceptOnly:true}:{id:id(),type:tool,x:clamp(x),y:clamp(y),x2:clamp(x),y2:clamp(y)}};P.objects.push(drag.create);selected=drag.create.id;render()});
cv.addEventListener('pointermove',e=>{if(!drag)return;if(drag.pan){V.x=drag.vx+e.clientX-drag.x;V.y=drag.vy+e.clientY-drag.y;render();return}const [x,y]=pointer(e);if(drag.create){drag.create.x2=clamp(x);drag.create.y2=clamp(y)}else if(drag.move){const o=drag.move;if(!drag.changed&&!['furniture','room','zone'].includes(o.type)){markSiteChanged();drag.changed=true}if(o.type==='furniture'){o.x=clamp(x-drag.ox);o.y=clamp(y-drag.oy)}else if(o.x2!=null){const dx=clamp(x-drag.ox)-o.x,dy=clamp(y-drag.oy)-o.y;o.x+=dx;o.y+=dy;o.x2+=dx;o.y2+=dy;if(o.type==='zone'){const item=P.furniture.find(f=>f.zoneId===o.id);if(item){item.x+=dx;item.y+=dy}}}else{o.x=clamp(x-drag.ox);o.y=clamp(y-drag.oy)}}render()});
addEventListener('pointerup',()=>{if(drag?.create?.type==='room'){const room=drag.create,corridor=P.objects.find(o=>o.type==='corridor');room.door.side=corridor&&(rect(room).y+rect(room).h/2)>=rect(corridor).y+rect(corridor).h/2?'north':'south'}if(drag&&!drag.pan)save();drag=null});cv.addEventListener('wheel',e=>{e.preventDefault();const r=cv.getBoundingClientRect(),mx=e.clientX-r.left,my=e.clientY-r.top,[wx,wy]=world(mx,my),z=e.deltaY<0?1.12:.89;V.scale=Math.max(.008,Math.min(.18,V.scale*z));V.x=mx-wx*V.scale;V.y=my-wy*V.scale;render()},{passive:false});
